insert into public.ao_schedule_sheets (id,source_id,name,role,cells) values ('2fbad023f47c408041b02b6209c86564','d7dc915358e139d8262d1169909e571e','Steps','alternate-or-template','[{"cell":"A1","value":"🙋🏻Here are some key steps to take note while creating your centre''s 2026 Schedule","type":"s","format":"General","comment":null},{"cell":"A2","value":"Step 1","type":"s","format":"General","comment":null},{"cell":"B2","value":"Ensure that the address, contact details and Whatsapp QR codes are correct.","type":"s","format":"General","comment":null},{"cell":"A3","value":"Step 2","type":"s","format":"General","comment":null},{"cell":"B3","value":"Duplicate the EMS Template Sheet by level groups (you may use the checklist below).\nHide the unnecessary subject columns for each level group.\n\nNote: For CL Template Sheet, please edit on the template itself accordingly.\nKindly DO NOT edit the format (i.e.: fonts, size of rows and columns, number of rows and columns, logos, QR codes, additional information and etc.).","type":"s","format":"General","comment":null},{"cell":"B4","value":false,"type":"b","format":"General","comment":null},{"cell":"C4","value":"Lower Primary (P1-P2)","type":"s","format":"General","comment":null},{"cell":"B5","value":false,"type":"b","format":"General","comment":null},{"cell":"C5","value":"Middle Primary (P3-P4)","type":"s","format":"General","comment":null},{"cell":"B6","value":false,"type":"b","format":"General","comment":null},{"cell":"C6","value":"Upper Primary (P5-P6)","type":"s","format":"General","comment":null},{"cell":"B7","value":false,"type":"b","format":"General","comment":null},{"cell":"C7","value":"Lower Secondary (S1-S2)","type":"s","format":"General","comment":null},{"cell":"B8","value":false,"type":"b","format":"General","comment":null},{"cell":"C8","value":"Upper Secondary (S3-S4/5)","type":"s","format":"General","comment":null},{"cell":"B9","value":false,"type":"b","format":"General","comment":null},{"cell":"C9","value":"IP (Y