insert into public.ao_schedule_sheets (id,source_id,name,role,cells) values ('f4f665215ef39d0d7de1ea20a8ae9693','202e8fd36e2df519de6fa78f8c479454','Steps','alternate-or-template','[{"cell":"A1","value":"🙋🏻Here are some key steps to take note while creating your centre''s 2026 Schedule","type":"s","format":"General","comment":null},{"cell":"A2","value":"Step 1","type":"s","format":"General","comment":null},{"cell":"B2","value":"Ensure that the address, contact details and Whatsapp QR codes are correct.","type":"s","format":"General","comment":null},{"cell":"A3","value":"Step 2","type":"s","format":"General","comment":null},{"cell":"B3","value":"Duplicate the EMS Template Sheet by level groups (you may use the checklist below).\nHide the unnecessary subject columns for each level group.\n\nNote: For CL Template Sheet, please edit on the template itself accordingly.\nKindly DO NOT edit the format (i.e.: fonts, size of rows and columns, number of rows and columns, logos, QR codes, additional information and etc.).","type":"s","format":"General","comment":null},{"cell":"B4","value":false,"type":"b","format":"General","comment":null},{"cell":"C4","value":"Lower Primary (P1-P2)","type":"s","format":"General","comment":null},{"cell":"B5","value":false,"type":"b","format":"General","comment":null},{"cell":"C5","value":"Middle Primary (P3-P4)","type":"s","format":"General","comment":null},{"cell":"B6","value":false,"type":"b","format":"General","comment":null},{"cell":"C6","value":"Upper Primary (P5-P6)","type":"s","format":"General","comment":null},{"cell":"B7","value":false,"type":"b","format":"General","comment":null},{"cell":"C7","value":"Lower Secondary (S1-S2)","type":"s","format":"General","comment":null},{"cell":"B8","value":false,"type":"b","format":"General","comment":null},{"cell":"C8","value":"Upper Secondary (S3-S4/5)","type":"s","format":"General","comment":null},{"cell":"B9","value":false,"type":"b","format":"General","comment":null},{"cell":"C9","value":"IP (Y3-Y4)","type":"s","format":"General","comment":null},{"cell":"B10","value":false,"type":"b","format":"General","comment":null},{"cell":"C10","value":"JC/IP (Y5-Y6)","type":"s","format":"General","comment":null},{"cell":"A11","value":"Step 3","type":"s","format":"General","comment":null},{"cell":"B11","value":"Download each sheet by PDF and save with the following file name: Term 1 2026 Schedule (EMS - Lower Pri)\n\nNote: At this step, merge the schedules and price lists and save them once more.","type":"s","format":"General","comment":null},{"cell":"A13","value":"Step 4","type":"s","format":"General","comment":null},{"cell":"B13","value":"Upload them back in the Google Drive Folder as PDF for easier access in sharing/printing\n\nNote: You may have separate folders within the Google Drive for Schedules only and Schedules with Price Lists.","type":"s","format":"General","comment":null}]') on conflict do nothing;
